from collections import deque
def dists(target9=True):
    d=[[None]*C for _ in range(R)]; q=deque()
    for r in range(R):
        for c in range(C):
            if (inp[r][c]==9)==target9: d[r][c]=0; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and d[nr][nc] is None:
                d[nr][nc]=d[r][c]+1; q.append((nr,nc))
    return d
