def rowcol_between():
    pred=set()
    for r in range(R):
        for c in range(C):
            if inp[r][c]==9: continue
            if any(inp[r][x]==9 for x in range(c)) and any(inp[r][x]==9 for x in range(c+1,C)): pred.add((r,c))
            elif any(inp[x][c]==9 for x in range(r)) and any(inp[x][c]==9 for x in range(r+1,R)): pred.add((r,c))
    return pred
